        row = JobParameterSet(parameters)
        source = row.get_source()
        if not source:
            raise JobCreationException(
                "No source identifier found. I can't create a job without knowing"
                " where to get the data"
            )

        # Do not replace ClientTool methods, on the instance or the class.
        # A previous dry-run left those mocks in place, so a later real run
        # still "succeeded" and never contacted the server.
        if dry_run:

            def create_pacs_job(*args, **kwargs):
                return _echo_dry_run_create(*args, **kwargs)

            def create_path_job(*args, **kwargs):
                return _echo_dry_run_create(*args, **kwargs)

        else:
            create_pacs_job = self.client_tool.create_pacs_job
            create_path_job = self.client_tool.create_path_job

        try:
            if row.is_pacs_type(source):
                response = create_pacs_job(
                    server=self.get_active_server(), **row.as_kwargs()
                )
            elif row.is_path_type(source):
                response = create_path_job(
                    server=self.get_active_server(), **row.as_kwargs()
                )
            else:
                raise JobCreationException(f"Unknown source '{source}'")

        except (APIClientException, AnonClientSettingsException) as e:
            raise JobCreationException(f"Error creating job for source {source}: {e}")

        return response.job_id

