        ------
        JobCreationException
            If creating jobs fails for any reason

        Returns
        -------
        int
            job id created
        """

        row = JobParameterSet(parameters)
        # Row lists coming back from a validated set sometimes omit defaults.
        # Put any missing configured defaults back so path and PACS jobs both
        # receive project and destination.
        missing_defaults = [
            param
            for param in self.default_parameters()
            if row.get_param_by_type(type(param)) is None
        ]
        if missing_defaults:
            current = getattr(row, "default_parameters", None)
            combined = list(current) + missing_defaults if current and not callable(current) else missing_defaults
            try:
                row.default_parameters = combined
            except Exception:
